static class D
{
    public static decimal F(decimal total, bool vip)
    {
        var rate = 0m;
        if (vip) rate += 0.10m;
        if (total > 1_000_000m) rate += 0.05m;
        return total * (1 - rate);
    }
}

Console.WriteLine(Rank(120));
Console.WriteLine(Rank(-5));

static string Rank(int points)
{
    if (points < 0)
        throw new ArgumentOutOfRangeException(nameof(points));
    if (points >= 100) return "Nòng cốt";
    if (points >= 50) return "Tích cực";
    return "Thành viên";
}

