#:sdk Microsoft.NET.Sdk.Web
#:property JsonSerializerIsReflectionEnabledByDefault=true
#:property EnableRequestDelegateGenerator=false
#:property NoWarn=IL2026;IL3050;$(NoWarn)
var builder = WebApplication.CreateBuilder(args);
builder.Logging.ClearProviders();
var app = builder.Build();
var customers = new List<Customer> { new(1, "An"), new(2, "Binh") };
app.MapGet("/customers/{id:int}", (int id) =>
    customers.FirstOrDefault(c => c.Id == id) is { } c
        ? Results.Ok(c)
        : Results.NotFound());
app.MapPost("/customers", (CreateReq r) =>
{
    var c = new Customer(customers.Max(x => x.Id) + 1, r.Name);
    customers.Add(c);
    return Results.Created($"/customers/{c.Id}", c);
});
app.Urls.Add("http://127.0.0.1:5187");
await app.StartAsync();
using var http = new HttpClient { BaseAddress = new Uri("http://127.0.0.1:5187") };
Console.WriteLine((int)(await http.GetAsync("/customers/9")).StatusCode);
Console.WriteLine((int)(await http.GetAsync("/customers/abc")).StatusCode);
Console.WriteLine((int)(await http.GetAsync("/customers/2")).StatusCode);
var resp = await http.PostAsync("/customers", new StringContent("{\"name\":\"C\"}", System.Text.Encoding.UTF8, "application/json"));
Console.WriteLine((int)resp.StatusCode + " " + resp.Headers.Location);
await app.StopAsync();
record Customer(int Id, string Name);
record CreateReq(string Name);
